// Agrupa las piezas filtradas en un solo lote para evaluarlas en una llamada.
const piezas = [];
for (const [i, item] of $input.all().entries()) {
  piezas.push({
    id: 'p' + (i + 1),
    titulo: item.json.title || '',
    url: (item.json.link || '').split('?utm')[0],
    fecha: item.json.isoDate || item.json.pubDate || '',
    resumen: (item.json.contentSnippet || '').slice(0, 500),
  });
}
// Tope de piezas por lote para no cortar la respuesta del modelo.
const lote = piezas.slice(0, 15);
return [{
  json: {
    semana: new Date().toISOString().slice(0, 10),
    n_recogidas: piezas.length,
    fuentes: lote,
  },
}];

