// Cruza las evaluaciones con el lote y separa aprobadas de descartadas.
const lote = $('Preparar lote').first().json;
let bruto = $input.first().json?.content?.[0]?.text ?? '';
bruto = bruto.replace(/```json/gi, '').replace(/```/g, '').trim();
let evaluaciones = [];
try {
  evaluaciones = JSON.parse(bruto).evaluaciones || [];
} catch (error) {
  evaluaciones = [];
}
const porId = {};
for (const ev of evaluaciones) porId[ev.id] = ev;
const UMBRAL = 3;
const aprobadas = [];
const descartadas = [];
for (const pieza of lote.fuentes) {
  const ev = porId[pieza.id] || { nota: 0, motivo: 'sin evaluacion: revisar a mano', duplicada_de: null };
  const conNota = { ...pieza, nota: ev.nota, motivo: ev.motivo };
  if (ev.nota >= UMBRAL && !ev.duplicada_de) aprobadas.push(conNota);
  else descartadas.push(conNota);
}
return [{
  json: {
    semana: lote.semana,
    n_recogidas: lote.n_recogidas,
    n_aprobadas: aprobadas.length,
    n_descartadas: descartadas.length,
    fuentes_aprobadas: JSON.stringify(aprobadas),
    detalle_evaluacion: JSON.stringify(evaluaciones).slice(0, 2000),
  },
}];

