// Monta el borrador final con cabecera y pie a partir de la sintesis.
const datos = $('Leer evaluacion').first().json;
let sintesis = $input.first().json?.content?.[0]?.text ?? '';
sintesis = sintesis.trim();
const cabecera = 'INFORME SEMANAL · ' + datos.semana + '\nElaborado con recogida automatica de fuentes y revision humana.\n\n';
const pie = '\n\n---\nRecogidas ' + datos.n_recogidas + ' piezas; ' + datos.n_aprobadas + ' superaron la evaluacion de credibilidad; ' + datos.n_descartadas + ' descartadas.';
return [{
  json: {
    semana: datos.semana,
    asunto: 'Informe semanal de vigilancia · ' + datos.semana,
    informe: cabecera + sintesis + pie,
    n_recogidas: datos.n_recogidas,
    n_aprobadas: datos.n_aprobadas,
  },
}];

